import nbformat,base64,re
nb=nbformat.read('analysis.ipynb',4)
n=0
for c in nb.cells:
    if c.cell_type=='code':
        for o in c.outputs:
            if o.get('output_type')=='error': print('ERR')
            if 'data' in o:
                if 'image/png' in o.data:
                    open(f'/tmp/build/fig{n}.png','wb').write(base64.b64decode(o.data['image/png'])); n+=1
                elif 'text/html' in o.data and '<style' in o.data['text/html']:
                    h=o.data['text/html']
                    rows=re.findall(r'<tr>(.*?)</tr>',h,re.S)
                    for r in rows: print(' | '.join(re.sub('<.*?>','',x) for x in re.findall(r'<t[dh].*?</t[dh]>',r,re.S)))
print(n)
